    BAR_COLORS = ['separator', 'background', 'statusline', 'focused_workspace', 'active_workspace', 'inactive_workspace', 'urgent_workspace']
    CLIENT_COLORS = ['client.focused', 'client.focused_inactive', 'client.unfocused', 'client.urgent']

    with open(infile) as f:
        lines = f.readlines()

    out_lines = []
    in_bar = False
    in_colors = False
    bar_has_colors = False
    bar_colors_found = set()
    client_colors_found = set()
    colors_indent = ""

    for orig_line in lines:
        orig_line = orig_line.rstrip('\n')
        m = re.match(r'^(\s*)bar\s+\{', orig_line)
        if m and not in_bar:
            in_bar = True
            bar_has_colors = False
            bar_colors_found = set()
            out_lines.append(orig_line)
            continue

