                out_lines.append(orig_line)
                continue

            m_close_match = re.match(r'^(\s*)\}', orig_line)
            m_close = m_close_match if (orig_line.split() and orig_line.split()[0] == '}') else None

            if m_close:
                if in_colors:
                    in_colors = False
                    for key in BAR_COLORS:
                        if key not in bar_colors_found and key in theme:
                            added_indent = colors_indent * 2 if colors_indent != "" else ""
                            vals = theme[key]
                            trailing = " " if 'workspace' in key else ""
                            out_lines.append(f"{added_indent}{key} {' '.join(vals)}{trailing}")
                    out_lines.append(orig_line)
                    continue
                elif in_bar:
                    if not bar_has_colors:
                        out_lines.append("  colors {")
                        for key in BAR_COLORS:
                            if key in theme:
                                vals = theme[key]
                                trailing = " " if 'workspace' in key else ""
                                out_lines.append(f"    {key} {' '.join(vals)}{trailing}")
                        out_lines.append("  }")
                    in_bar = False
                    out_lines.append(orig_line)
                    continue

        replaced = False
        if in_colors:
            for key in BAR_COLORS:
                m = re.match(r'^(\s*)' + key + r'(\s+.*|$)', orig_line)
                if m:
                    bar_colors_found.add(key)
                    prefix = m.group(1)
                    parts = orig_line.strip().split()
                    extra = " " + parts[3] if len(parts) >= 4 else ""
                    if key in theme:
                        out_lines.append(f"{prefix}{key} {' '.join(theme[key])}{extra}")
                        replaced = True
                    break

        if not replaced:
            for key in CLIENT_COLORS:
                m = re.match(r'^(\s*)' + key + r'(\s+.*|$)', orig_line)
                if m:
                    client_colors_found.add(key)
                    prefix = m.group(1)
                    if key in theme:
                        out_lines.append(f"{prefix}{key} {' '.join(theme[key])}")
                        replaced = True
                    break

        if not replaced:
            out_lines.append(orig_line)

    for key in CLIENT_COLORS:
        if key not in client_colors_found and key in theme:
            out_lines.append(f"{key} {' '.join(theme[key])}")

    if outfile:
        # Save to temp file
        os.makedirs(temp_dir, exist_ok=True)
        temp_file = os.path.join(temp_dir, "config-input")
        sys.stderr.write(f"saving config at {infile} to {temp_file}\n")
        with open(temp_file, 'w') as f:
            for l in out_lines: f.write(l + "\n")
        with open(outfile, 'w') as f:
            for l in out_lines: f.write(l + "\n")
    else:
        for l in out_lines: print(l)

